//! UI strings in every language Omarchy ships.
//!
//! The language is Omarchy's: the code in `~/.config/omarchy/language`
//! (or `$OMARCHY_LANGUAGE_FILE`), English when the file is missing, exactly
//! as `omarchy-i18n` and the shell resolve it. Catalogs live in `i18n/` and
//! are compiled into the binary; a missing key falls back to English.

use std::collections::HashMap;
use std::sync::{OnceLock, RwLock};

use crate::paths;

// CATALOGS: &[(&str, &str)], generated by build.rs from i18n/*.toml.
include!(concat!(env!("OUT_DIR"), "/catalogs.rs"));

const RTL: &[&str] = &["ar", "fa", "he", "ur"];

struct Catalog {
    code: String,
    strings: HashMap<String, String>,
}

fn parse(code: &str) -> Catalog {
    let raw = CATALOGS
        .iter()
        .find(|(c, _)| *c == code)
        .map(|(_, s)| *s)
        .unwrap_or("");
    let strings = raw
        .parse::<toml::Table>()
        .map(|t| {
            t.into_iter()
                .filter_map(|(k, v)| v.as_str().map(|s| (k, s.to_string())))
                .collect()
        })
        .unwrap_or_default();
    Catalog {
        code: code.to_string(),
        strings,
    }
}

fn english() -> &'static Catalog {
    static EN: OnceLock<Catalog> = OnceLock::new();
    EN.get_or_init(|| parse("en"))
}

fn current() -> &'static RwLock<Option<Catalog>> {
    static CURRENT: RwLock<Option<Catalog>> = RwLock::new(None);
    &CURRENT
}

pub fn language_file() -> std::path::PathBuf {
    match std::env::var_os("OMARCHY_LANGUAGE_FILE") {
        Some(p) if !p.is_empty() => p.into(),
        _ => paths::config_home().join("omarchy/language"),
    }
}

/// The catalog code for a raw Omarchy language code: an exact match, then a
/// catalog with the same base language (`es` → `es-MX`), then English.
pub fn resolve(raw: &str) -> &'static str {
    let code = raw.trim();
    if let Some((c, _)) = CATALOGS.iter().find(|(c, _)| c.eq_ignore_ascii_case(code)) {
        return c;
    }
    let base = code.split('-').next().unwrap_or("").to_ascii_lowercase();
    if !base.is_empty() {
        if let Some((c, _)) = CATALOGS
            .iter()
            .find(|(c, _)| c.split('-').next() == Some(base.as_str()))
        {
            return c;
        }
    }
    "en"
}

fn wanted() -> &'static str {
    let raw = std::fs::read_to_string(language_file()).unwrap_or_default();
    resolve(raw.lines().next().unwrap_or(""))
}

/// Reads Omarchy's language again. Returns true when it changed.
pub fn reload() -> bool {
    let code = wanted();
    let mut slot = current().write().unwrap_or_else(|e| e.into_inner());
    if slot.as_ref().is_some_and(|c| c.code == code) {
        return false;
    }
    *slot = Some(parse(code));
    true
}

/// Tests pin a language without touching Omarchy's file. Use
/// `testutil::language`, which also serializes the tests that do this.
#[cfg(test)]
pub fn set_for_test(code: &str) {
    let mut slot = current().write().unwrap_or_else(|e| e.into_inner());
    *slot = Some(parse(resolve(code)));
}

pub fn code() -> String {
    let slot = current().read().unwrap_or_else(|e| e.into_inner());
    slot.as_ref()
        .map(|c| c.code.clone())
        .unwrap_or_else(|| "en".into())
}

pub fn rtl() -> bool {
    let code = code();
    RTL.contains(&code.split('-').next().unwrap_or(""))
}

pub fn tr(key: &str) -> String {
    {
        let slot = current().read().unwrap_or_else(|e| e.into_inner());
        if let Some(s) = slot.as_ref().and_then(|c| c.strings.get(key)) {
            return s.clone();
        }
    }
    english()
        .strings
        .get(key)
        .cloned()
        .unwrap_or_else(|| key.to_string())
}

/// `tr` with `{placeholder}` substitution.
pub fn trf(key: &str, args: &[(&str, &str)]) -> String {
    let mut out = tr(key);
    for (k, v) in args {
        out = out.replace(&format!("{{{k}}}"), v);
    }
    out
}

/// The built-in reminders Pharos creates on first run, and the name a new
/// reminder starts with. Their names are never stored until the user edits
/// them, so they follow the language.
pub const PRESETS: &[(&str, u32, bool)] = &[
    ("water", 20, true),
    ("hands", 24, false),
    ("legs", 40, true),
    ("eyes", 10, true),
    ("posture", 30, true),
];

pub const NEW_PRESET: &str = "new";

pub fn preset_name(preset: &str) -> Option<String> {
    if preset == NEW_PRESET {
        return Some(tr("new_reminder"));
    }
    let key = format!("preset_{preset}");
    english().strings.contains_key(&key).then(|| tr(&key))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Omarchy's language codes (`$OMARCHY_PATH/default/i18n/locales.json`).
    const OMARCHY: &[&str] = &[
        "ar", "bg", "bn", "ca", "cs", "da", "de", "el", "en", "es-MX", "et", "fa", "fi", "fil",
        "fr", "ga", "he", "hi", "hr", "hu", "id", "is", "it", "ja", "ko", "lt", "lv", "ms", "nl",
        "no", "pl", "pt", "pt-BR", "ro", "ru", "si", "sk", "sl", "sr", "sv", "sw", "ta", "th",
        "tr", "uk", "ur", "uz", "vi", "zh-CN", "zh-TW",
    ];

    fn placeholders(s: &str) -> Vec<String> {
        let mut out: Vec<String> = s
            .split('{')
            .skip(1)
            .filter_map(|p| p.split_once('}').map(|(k, _)| k.to_string()))
            .collect();
        out.sort();
        out
    }

    #[test]
    fn every_omarchy_language_is_complete() {
        let en = parse("en");
        for code in OMARCHY {
            assert!(
                CATALOGS.iter().any(|(c, _)| c == code),
                "missing catalog for {code}"
            );
            let cat = parse(code);
            for (key, value) in &en.strings {
                let got = cat
                    .strings
                    .get(key)
                    .unwrap_or_else(|| panic!("{code}: missing key {key}"));
                assert!(!got.trim().is_empty(), "{code}: empty {key}");
                assert_eq!(
                    placeholders(got),
                    placeholders(value),
                    "{code}: placeholders differ in {key}"
                );
            }
            for key in cat.strings.keys() {
                assert!(en.strings.contains_key(key), "{code}: unknown key {key}");
            }
        }
    }

    #[test]
    fn hints_have_no_quit_key() {
        // Omarchy closes windows with Super+W; Pharos keeps running.
        for (code, _) in CATALOGS {
            let cat = parse(code);
            for key in ["hint_normal", "hint_editing"] {
                assert!(!cat.strings[key].contains("ctrl+q"), "{code}: {key}");
            }
        }
    }

    #[test]
    fn resolves_like_omarchy() {
        assert_eq!(resolve("es-MX"), "es-MX");
        assert_eq!(resolve("es"), "es-MX");
        assert_eq!(resolve("pt-BR"), "pt-BR");
        assert_eq!(resolve("zh-TW"), "zh-TW");
        assert_eq!(resolve(""), "en");
        assert_eq!(resolve("xx"), "en");
    }

    use crate::testutil::language;

    #[test]
    fn substitutes_placeholders() {
        let _l = language("en");
        assert_eq!(trf("minutes", &[("n", "20")]), "20 min");
        assert_eq!(
            trf("next", &[("name", "Drink water"), ("time", "12:04")]),
            "Next: Drink water in 12:04"
        );
        let _ = _l;
    }

    #[test]
    fn spanish_matches_the_original_app() {
        let _l = language("es-MX");
        let names: Vec<String> = PRESETS
            .iter()
            .map(|(p, ..)| preset_name(p).unwrap())
            .collect();
        assert_eq!(
            names,
            [
                "Tomar agua",
                "Estira tus manos",
                "Estira tus piernas",
                "Relaja tus ojos",
                "Siéntate bien"
            ]
        );
        assert_eq!(tr("tray_open"), "Abrir");
        assert_eq!(tr("tray_turn_off"), "Desactivar");
        assert_eq!(tr("tray_quit"), "Salir");
    }

    #[test]
    fn every_language_translates_the_reminders() {
        // Spelled the same as English and correct: Dutch "Drink water".
        const SAME_AS_ENGLISH: &[(&str, &str)] = &[("nl", "preset_water")];
        let en = parse("en");
        for (code, _) in CATALOGS.iter().filter(|(c, _)| *c != "en") {
            let cat = parse(code);
            for (preset, ..) in PRESETS {
                let key = format!("preset_{preset}");
                if SAME_AS_ENGLISH.contains(&(*code, key.as_str())) {
                    continue;
                }
                assert_ne!(
                    cat.strings[&key], en.strings[&key],
                    "{code}: {key} is still English"
                );
            }
        }
    }

    #[test]
    fn right_to_left_languages() {
        for (code, rtl_expected) in [
            ("ar", true),
            ("fa", true),
            ("he", true),
            ("ur", true),
            ("en", false),
            ("es-MX", false),
            ("ja", false),
        ] {
            let _l = language(code);
            assert_eq!(rtl(), rtl_expected, "{code}");
        }
    }

    #[test]
    fn unknown_keys_and_presets() {
        let _l = language("en");
        assert_eq!(tr("no_such_key"), "no_such_key");
        assert_eq!(preset_name("no_such_preset"), None);
        assert_eq!(preset_name(NEW_PRESET).as_deref(), Some("New reminder"));
    }

    #[test]
    fn every_catalog_is_valid_toml() {
        for (code, raw) in CATALOGS {
            assert!(
                raw.parse::<toml::Table>().is_ok(),
                "{code}.toml does not parse"
            );
        }
        assert_eq!(CATALOGS.len(), 50);
    }
}
